-- ---------------------------------------------------------------- state row
SELECT jsonb_build_object(
  'new_md5', jsonb_build_object(
    'verdict', md5(pg_get_functiondef('public.readiness_verdict(uuid,uuid)'::regprocedure)),
    'isoFor', md5(pg_get_functiondef('public.dept_iso_hours_for(uuid,timestamp with time zone,timestamp with time zone)'::regprocedure)),
    'byStation', md5(pg_get_functiondef('public.dept_iso_hours_by_station(timestamp with time zone,timestamp with time zone)'::regprocedure)),
    'shifts', md5(pg_get_functiondef('public.dept_station_shifts(timestamp with time zone,timestamp with time zone)'::regprocedure)),
    'myShifts', md5(pg_get_functiondef('public.my_station_shifts(timestamp with time zone,timestamp with time zone)'::regprocedure)),
    'byMonth', md5(pg_get_functiondef('public.dept_iso_hours_by_month(timestamp with time zone[],timestamp with time zone[])'::regprocedure))),
  'ws4d_marked',        (SELECT count(*) FROM pg_proc p WHERE p.oid = ANY (ARRAY['public.readiness_verdict(uuid,uuid)'::regprocedure, 'public.dept_iso_hours_for(uuid,timestamp with time zone,timestamp with time zone)'::regprocedure, 'public.dept_iso_hours_by_station(timestamp with time zone,timestamp with time zone)'::regprocedure, 'public.dept_station_shifts(timestamp with time zone,timestamp with time zone)'::regprocedure, 'public.my_station_shifts(timestamp with time zone,timestamp with time zone)'::regprocedure, 'public.dept_iso_hours_by_month(timestamp with time zone[],timestamp with time zone[])'::regprocedure]::oid[])
                            AND position('WS-4d' in pg_get_functiondef(p.oid)) > 0),
  'attested_training_md5', md5(pg_get_functiondef('public.attested_training(uuid,timestamp with time zone,timestamp with time zone)'::regprocedure)),
  'meetings_flagged',   (SELECT count(*) FROM public.training_sessions WHERE is_meeting),
  'voided_rows',        (SELECT count(*) FROM public.station_presence WHERE checked_out_at IS NOT NULL AND checked_out_at = checked_in_at AND kind IN ('standby', 'training')),
  'total_policies',     (SELECT count(*) FROM pg_policies WHERE schemaname = 'public'),
  'fn_count',           (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f'),
  'verified_presence',  (SELECT count(*) FROM public.station_presence WHERE verified)
) AS state;
